# Framework-free agent loop with a tool registry, validation and max_steps.
import json

TOOLS = {}

def tool(fn):
    TOOLS[fn.__name__] = fn
    return fn

@tool
def describe_table(name: str) -> dict:
    allowed = {"orders": ["id", "org_id", "total", "created_at"]}
    if name not in allowed:
        return {"error": f"unknown table {name}"}
    return {"columns": allowed[name]}

def run_agent(call_model, user_msg: str, max_steps: int = 8) -> str:
    messages = [{"role": "user", "content": user_msg}]
    for step in range(max_steps):
        reply = call_model(messages, tools=list(TOOLS))     # provider SDK call
        if reply.get("tool_call") is None:
            return reply["content"]                         # final answer
        call = reply["tool_call"]
        fn = TOOLS.get(call["name"])
        try:
            result = fn(**call["arguments"]) if fn else {"error": "unknown tool"}
        except Exception as exc:                            # tool errors become observations
            result = {"error": str(exc)}
        messages.append({"role": "assistant", "tool_call": call})
        messages.append({"role": "tool", "name": call["name"], "content": json.dumps(result)[:4000]})
    return "Stopped: step limit reached without a final answer."
```

