def run(call_model, messages, tools, max_steps=8):
    for _ in range(max_steps):
        reply = call_model(messages, tools=tools.schemas())
        if not reply.tool_calls:
            return reply.text
        messages.append(reply.as_message())
        for call in reply.tool_calls:
            try:
                args = tools.validate(call.name, call.arguments)   # Pydantic
                result = tools.run(call.name, args)
            except Exception as e:
                result = {"error": str(e)}
            messages.append({"role": "tool", "id": call.id, "content": truncate(result)})
    return "stopped: step limit"
```
Key points: the model only proposes; code validates and executes; errors become observations; hard limits on steps/tokens/time; each step traced (prompt, call, result, tokens, latency).
